source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # Colored cells on the bottom edge mark the vertical lines to extend.
    markers = [c for c in range(w) if out[h - 1][c] != 0]
    crossings = {c: [] for c in markers}

    # Complete the one-cell gaps in horizontal stripes at marked columns.
    for r in range(h):
        for c in markers:
            if 0 < c < w - 1 and out[r][c] == 0:
                color = out[r][c - 1]
                if color != 0 and out[r][c + 1] == color:
                    out[r][c] = color
                    crossings[c].append((r, color))

    # Extend each marked line upward, changing to each stripe's color at
    # its crossing; keep the marker's own color below the lowest stripe.
    for c in markers:
        previous = -1
        for r, color in crossings[c]:
            for y in range(previous + 1, r + 1):
                out[y][c] = color
            previous = r
        if crossings[c]:
            marker_color = grid[h - 1][c]
            for y in range(previous + 1, h):
                out[y][c] = marker_color
    return out
'''
